# VexelRay Inspector diagnostics - generated by vexelray-installer. Do not edit by hand; regenerate it.
#
# Checks this computer against the system requirements of VexelRay Inspector and writes a report to attach to a bug
# report: Windows, processor, memory, disk, the displays (resolution, refresh rate, scaling, HDR), every GPU
# as DXGI / Direct3D 12 and as Vulkan see it, a test flip-model swapchain, the Vulkan present modes and
# surface formats, implicit Vulkan layers and the applications installed beside it. Nothing is sent anywhere;
# the report is a text file for you to read and attach.
#
#   & "<install folder>\diagnose.cmd"     after installing
#   irm https://raw.githubusercontent.com/sibarum/vexelray-dist/main/apps/inspector/diagnose.ps1 | iex   without installing
#
# Arguments (when run from a file or diagnose.cmd):
#   -Out <file>  write the report there   -Copy  also copy it to the clipboard   -Json  write JSON instead
# install.ps1 runs it with -Check, which returns the result instead of printing it.

$DiagCfg = '{"id":"inspector","name":"VexelRay Inspector","publisher":"sibarum","description":"DevTools for VexelRay applications, drawn as clockwork: attach to a running app and watch its frame loop beat, park and stall.","manifestUrl":"https://raw.githubusercontent.com/sibarum/vexelray-dist/main/apps/inspector/manifest.json","registryDir":"%LOCALAPPDATA%\\vexelray-installer\\installs","issuesUrl":"https://github.com/sibarum/vexelray-dist/issues/new"}' | ConvertFrom-Json

function VdRegistryDir {
    if ($env:INSTALL_REGISTRY_DIR) { return $env:INSTALL_REGISTRY_DIR }
    [Environment]::ExpandEnvironmentVariables($DiagCfg.registryDir)
}

# Runs a block; a failure becomes an { error } entry in the report instead of ending it.
function VdTry([scriptblock]$b) {
    try { & $b } catch { [ordered]@{ error = $_.Exception.Message } }
}

function VdMb($bytes) { if ($bytes) { [long]([double]$bytes / 1MB) } else { $null } }

# 1.3 / 1.3.280 / 10.0.19041 as a [version]; nothing comparable becomes 0.0
function VdVer([string]$v) {
    $m = [regex]::Match([string]$v, '\d+(\.\d+){0,3}')
    $s = $m.Value
    if ($s -notmatch '\.') { $s = "$s.0" }
    try { [version]$s } catch { [version]'0.0' }
}

$VdLevels = @{ '11_0' = 0xb000; '11_1' = 0xb100; '12_0' = 0xc000; '12_1' = 0xc100; '12_2' = 0xc200 }
function VdLevel([string]$l) { if ($l -and $VdLevels.ContainsKey($l)) { $VdLevels[$l] } else { 0 } }

# ---- the GPU probe: runs in a powershell.exe of its own -------------------------------------
# DXGI, Direct3D 12 and Vulkan are called natively. A broken driver can crash or hang the process that calls
# it, so the probe never runs in the installer's own process: it writes JSON to a file and is killed if it
# takes too long.

$VdProbeSource = @'
using System;
using System.Collections;
using System.Collections.Generic;
using System.Collections.Specialized;
using System.Globalization;
using System.Runtime.InteropServices;

namespace ViDiag {
public static class Probe {
    // ---- Win32 / DXGI / D3D12 ----
    [DllImport("dxgi.dll")] static extern int CreateDXGIFactory1(ref Guid riid, out IntPtr factory);
    [DllImport("d3d12.dll", EntryPoint = "D3D12CreateDevice")] static extern int D3D12Supports(IntPtr adapter, int level, ref Guid riid, IntPtr none);
    [DllImport("d3d12.dll", EntryPoint = "D3D12CreateDevice")] static extern int D3D12CreateDevice(IntPtr adapter, int level, ref Guid riid, out IntPtr device);
    [DllImport("user32.dll", CharSet = CharSet.Unicode)] static extern IntPtr CreateWindowExW(uint ex, string cls, string title, uint style, int x, int y, int w, int h, IntPtr parent, IntPtr menu, IntPtr inst, IntPtr param);
    [DllImport("user32.dll")] static extern bool DestroyWindow(IntPtr hwnd);
    [DllImport("user32.dll", CharSet = CharSet.Unicode)] static extern bool EnumDisplaySettingsW(string device, int mode, ref DevMode dm);
    [DllImport("user32.dll")] static extern IntPtr SetThreadDpiAwarenessContext(IntPtr context);
    [DllImport("shcore.dll")] static extern int GetDpiForMonitor(IntPtr monitor, int type, out uint x, out uint y);
    [DllImport("kernel32.dll", CharSet = CharSet.Unicode)] static extern IntPtr GetModuleHandleW(string name);

    static readonly Guid IID_Factory1 = new Guid("770aae78-f26f-4dba-a829-253c83d1b387");
    static readonly Guid IID_Factory2 = new Guid("50c83a1c-e072-4c48-87b0-3630fa36a6d0");
    static readonly Guid IID_Factory5 = new Guid("7632e1f5-ee65-4dca-87fd-84cd75f8838d");
    static readonly Guid IID_Factory6 = new Guid("c1b6694f-ff09-44a9-b03c-77900a0a1d17");
    static readonly Guid IID_Adapter1 = new Guid("29038f61-3839-4626-91fd-086879011a05");
    static readonly Guid IID_Output2 = new Guid("595e39d1-2724-4663-99b1-da969de28364");
    static readonly Guid IID_Output6 = new Guid("068346e8-aaec-4b84-add7-137f513f77a1");
    static readonly Guid IID_SwapChain3 = new Guid("94d99bdb-f1f8-4ab0-b236-7da0170edab1");
    static readonly Guid IID_D3D12Device = new Guid("189819f1-1db6-4b57-be54-1821339b85f7");
    static readonly Guid IID_D3D12Queue = new Guid("0ec870a6-5d7e-4c22-8cfc-5baae07616ed");

    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
    struct AdapterDesc1 {
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 128)] public string Description;
        public uint VendorId, DeviceId, SubSysId, Revision;
        public UIntPtr DedicatedVideoMemory, DedicatedSystemMemory, SharedSystemMemory;
        public uint LuidLow; public int LuidHigh; public uint Flags;
    }
    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
    struct OutputDesc {
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 32)] public string DeviceName;
        public int Left, Top, Right, Bottom, Attached, Rotation; public IntPtr Monitor;
    }
    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
    struct OutputDesc1 {
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 32)] public string DeviceName;
        public int Left, Top, Right, Bottom, Attached, Rotation; public IntPtr Monitor;
        public uint BitsPerColor; public int ColorSpace;
        [MarshalAs(UnmanagedType.ByValArray, SizeConst = 8)] public float[] Primaries;
        public float MinLuminance, MaxLuminance, MaxFullFrameLuminance;
    }
    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
    struct DevMode {
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 32)] public string dmDeviceName;
        public short dmSpecVersion, dmDriverVersion, dmSize, dmDriverExtra;
        public int dmFields, dmPositionX, dmPositionY, dmDisplayOrientation, dmDisplayFixedOutput;
        public short dmColor, dmDuplex, dmYResolution, dmTTOption, dmCollate;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 32)] public string dmFormName;
        public short dmLogPixels;
        public int dmBitsPerPel, dmPelsWidth, dmPelsHeight, dmDisplayFlags, dmDisplayFrequency;
        public int dmICMMethod, dmICMIntent, dmMediaType, dmDitherType, dmReserved1, dmReserved2, dmPanningWidth, dmPanningHeight;
    }
    [StructLayout(LayoutKind.Sequential)]
    struct SwapChainDesc1 {
        public uint Width, Height; public int Format, Stereo; public uint SampleCount, SampleQuality, BufferUsage, BufferCount;
        public int Scaling, SwapEffect, AlphaMode; public uint Flags;
    }
    [StructLayout(LayoutKind.Sequential)]
    struct QueueDesc { public int Type, Priority, Flags; public uint NodeMask; }

    [UnmanagedFunctionPointer(CallingConvention.StdCall)] delegate int PtrAt(IntPtr self, uint index, out IntPtr result);
    [UnmanagedFunctionPointer(CallingConvention.StdCall)] delegate int GetAdapterDesc1(IntPtr self, out AdapterDesc1 d);
    [UnmanagedFunctionPointer(CallingConvention.StdCall)] delegate int GetOutputDesc(IntPtr self, out OutputDesc d);
    [UnmanagedFunctionPointer(CallingConvention.StdCall)] delegate int GetOutputDesc1(IntPtr self, out OutputDesc1 d);
    [UnmanagedFunctionPointer(CallingConvention.StdCall)] delegate int CheckFeature(IntPtr self, int feature, ref int data, int size);
    [UnmanagedFunctionPointer(CallingConvention.StdCall)] delegate int NoArgs(IntPtr self);
    [UnmanagedFunctionPointer(CallingConvention.StdCall)] delegate int OutFlags(IntPtr self, out uint flags);
    [UnmanagedFunctionPointer(CallingConvention.StdCall)] delegate int ByPreference(IntPtr self, uint index, int preference, ref Guid iid, out IntPtr adapter);
    [UnmanagedFunctionPointer(CallingConvention.StdCall)] delegate int CreateQueue(IntPtr self, ref QueueDesc d, ref Guid iid, out IntPtr queue);
    [UnmanagedFunctionPointer(CallingConvention.StdCall)] delegate int CreateSwapForHwnd(IntPtr self, IntPtr device, IntPtr hwnd, ref SwapChainDesc1 d, IntPtr fullscreen, IntPtr restrict, out IntPtr swapchain);
    [UnmanagedFunctionPointer(CallingConvention.StdCall)] delegate int CheckColorSpace(IntPtr self, int colorSpace, out uint flags);

    // vtable slots, from the Windows SDK's C *Vtbl structs
    const int FACTORY1_ENUM_ADAPTERS1 = 12, FACTORY2_CREATE_SWAPCHAIN_FOR_HWND = 15, FACTORY5_CHECK_FEATURE = 28,
              FACTORY6_BY_PREFERENCE = 29, ADAPTER_ENUM_OUTPUTS = 7, ADAPTER1_GET_DESC1 = 10, OUTPUT_GET_DESC = 7,
              OUTPUT2_SUPPORTS_OVERLAYS = 23, OUTPUT6_GET_DESC1 = 27, OUTPUT6_HW_COMPOSITION = 28,
              DEVICE_CREATE_QUEUE = 8, SWAPCHAIN3_CHECK_COLOR_SPACE = 37;

    static T Method<T>(IntPtr obj, int slot) where T : class {
        IntPtr fn = Marshal.ReadIntPtr(Marshal.ReadIntPtr(obj), slot * IntPtr.Size);
        return Marshal.GetDelegateForFunctionPointer(fn, typeof(T)) as T;
    }
    static IntPtr QI(IntPtr obj, Guid iid) { IntPtr r; return Marshal.QueryInterface(obj, ref iid, out r) == 0 ? r : IntPtr.Zero; }
    static void Release(IntPtr p) { if (p != IntPtr.Zero) Marshal.Release(p); }
    static string Hr(int hr) { return "HRESULT 0x" + hr.ToString("X8"); }
    static string Hex(uint v) { return "0x" + v.ToString("X4"); }
    static string Luid(uint low, int high) { return high.ToString("X8") + "-" + low.ToString("X8"); }
    static string Level(int l) { return ((l >> 12) & 0xf) + "_" + ((l >> 8) & 0xf); }
    static OrderedDictionary Error(string message) { OrderedDictionary o = new OrderedDictionary(); o["error"] = message; return o; }

    static object Guard(Func<object> f) {
        try { return f(); }
        catch (DllNotFoundException e) { return Error("not available: " + e.Message); }
        catch (Exception e) { return Error(e.GetType().Name + ": " + e.Message); }
    }

    public static OrderedDictionary Run() {
        OrderedDictionary r = new OrderedDictionary();
        r["bits"] = IntPtr.Size * 8;
        try { SetThreadDpiAwarenessContext(new IntPtr(-4)); } catch (Exception) { }  // per-monitor v2: real DPI and pixels
        // a window that is never shown: what a swapchain and a Vulkan surface are created for
        IntPtr hwnd = CreateWindowExW(0, "STATIC", "diagnose", 0x00CF0000, 0, 0, 640, 480, IntPtr.Zero, IntPtr.Zero, GetModuleHandleW(null), IntPtr.Zero);
        try {
            r["dxgi"] = Guard(delegate { return Dxgi(hwnd); });
            r["vulkan"] = Guard(delegate { return Vulkan(hwnd); });
        } finally {
            if (hwnd != IntPtr.Zero) DestroyWindow(hwnd);
            foreach (IntPtr p in allocations) Marshal.FreeHGlobal(p);
            allocations.Clear();
        }
        return r;
    }

    // ---- DXGI ----
    static OrderedDictionary Dxgi(IntPtr hwnd) {
        OrderedDictionary o = new OrderedDictionary();
        Guid iid = IID_Factory1; IntPtr f;
        int hr = CreateDXGIFactory1(ref iid, out f);
        if (hr < 0) return Error("CreateDXGIFactory1 failed: " + Hr(hr));
        try {
            IntPtr f5 = QI(f, IID_Factory5);
            if (f5 != IntPtr.Zero) {
                int allow = 0;
                o["tearing"] = Method<CheckFeature>(f5, FACTORY5_CHECK_FEATURE)(f5, 0, ref allow, 4) >= 0 && allow != 0;
                Release(f5);
            } else o["tearing"] = false;
            IntPtr f6 = QI(f, IID_Factory6);
            if (f6 != IntPtr.Zero) {
                o["highPerformance"] = Preferred(f6, 2);
                o["minimumPower"] = Preferred(f6, 1);
                Release(f6);
            }
            ArrayList adapters = new ArrayList();
            for (uint i = 0; ; i++) {
                IntPtr a;
                if (Method<PtrAt>(f, FACTORY1_ENUM_ADAPTERS1)(f, i, out a) < 0) break;
                try { adapters.Add(Adapter(f, a, hwnd)); } finally { Release(a); }
            }
            o["adapters"] = adapters;
        } finally { Release(f); }
        return o;
    }

    static string Preferred(IntPtr f6, int preference) {
        Guid iid = IID_Adapter1; IntPtr a;
        if (Method<ByPreference>(f6, FACTORY6_BY_PREFERENCE)(f6, 0, preference, ref iid, out a) < 0) return null;
        try { AdapterDesc1 d; return Method<GetAdapterDesc1>(a, ADAPTER1_GET_DESC1)(a, out d) < 0 ? null : d.Description; }
        finally { Release(a); }
    }

    static OrderedDictionary Adapter(IntPtr factory, IntPtr a, IntPtr hwnd) {
        OrderedDictionary o = new OrderedDictionary();
        AdapterDesc1 d;
        int hr = Method<GetAdapterDesc1>(a, ADAPTER1_GET_DESC1)(a, out d);
        if (hr < 0) return Error("GetDesc1 failed: " + Hr(hr));
        bool software = (d.Flags & 2) != 0;
        o["name"] = d.Description;
        o["vendorId"] = Hex(d.VendorId);
        o["deviceId"] = Hex(d.DeviceId);
        o["subsystemId"] = "0x" + d.SubSysId.ToString("X8");
        o["revision"] = d.Revision;
        o["luid"] = Luid(d.LuidLow, d.LuidHigh);
        o["dedicatedVideoMb"] = (long)(d.DedicatedVideoMemory.ToUInt64() / 1048576);
        o["dedicatedSystemMb"] = (long)(d.DedicatedSystemMemory.ToUInt64() / 1048576);
        o["sharedSystemMb"] = (long)(d.SharedSystemMemory.ToUInt64() / 1048576);
        o["software"] = software;
        string level = null; int last = 0;
        try {
            foreach (int l in new int[] { 0xc200, 0xc100, 0xc000, 0xb100, 0xb000 }) {
                Guid dev = IID_D3D12Device;
                last = D3D12Supports(a, l, ref dev, IntPtr.Zero);
                if (last >= 0) { level = Level(l); break; }
            }
            o["d3d12"] = level;
            if (level == null) o["d3d12Error"] = Hr(last);
        } catch (DllNotFoundException) { o["d3d12"] = null; o["d3d12Error"] = "d3d12.dll is not available"; }
        if (level != null && !software) o["swapchain"] = Guard(delegate { return Swapchain(factory, a, hwnd); });
        ArrayList outputs = new ArrayList();
        for (uint i = 0; ; i++) {
            IntPtr op;
            if (Method<PtrAt>(a, ADAPTER_ENUM_OUTPUTS)(a, i, out op) < 0) break;
            try { outputs.Add(Guard(delegate { return Output(op); })); } finally { Release(op); }
        }
        o["outputs"] = outputs;
        return o;
    }

    // The swapchain a VexelRay window presents through: a D3D12 queue, flip-discard, BGRA8, unscaled, with a
    // frame-latency waitable. Then the same in 10-bit to see whether an HDR10 colour space would be accepted.
    static OrderedDictionary Swapchain(IntPtr factory, IntPtr adapter, IntPtr hwnd) {
        OrderedDictionary o = new OrderedDictionary();
        if (hwnd == IntPtr.Zero) return Error("no window to create a swapchain for");
        Guid iid = IID_D3D12Device; IntPtr dev = IntPtr.Zero, queue = IntPtr.Zero, f2 = IntPtr.Zero;
        int hr = D3D12CreateDevice(adapter, 0xb000, ref iid, out dev);
        if (hr < 0) return Error("D3D12CreateDevice failed: " + Hr(hr));
        try {
            QueueDesc qd = new QueueDesc();
            Guid qiid = IID_D3D12Queue;
            hr = Method<CreateQueue>(dev, DEVICE_CREATE_QUEUE)(dev, ref qd, ref qiid, out queue);
            if (hr < 0) return Error("CreateCommandQueue failed: " + Hr(hr));
            f2 = QI(factory, IID_Factory2);
            if (f2 == IntPtr.Zero) return Error("IDXGIFactory2 is not available");
            o["flipDiscard"] = TrySwapchain(f2, queue, hwnd, 87, -1);
            o["hdr10"] = TrySwapchain(f2, queue, hwnd, 24, 12);
        } finally { Release(f2); Release(queue); Release(dev); }
        return o;
    }

    // "ok", or why not; with a colour space, whether the swapchain can present in it
    static string TrySwapchain(IntPtr f2, IntPtr queue, IntPtr hwnd, int format, int colorSpace) {
        SwapChainDesc1 sd = new SwapChainDesc1();
        sd.Width = 640; sd.Height = 480; sd.Format = format; sd.SampleCount = 1; sd.BufferUsage = 0x20;
        sd.BufferCount = 2; sd.Scaling = 1; sd.SwapEffect = 4; sd.Flags = 64;
        IntPtr sc;
        int hr = Method<CreateSwapForHwnd>(f2, FACTORY2_CREATE_SWAPCHAIN_FOR_HWND)(f2, queue, hwnd, ref sd, IntPtr.Zero, IntPtr.Zero, out sc);
        if (hr < 0) return "failed: " + Hr(hr);
        try {
            if (colorSpace < 0) return "ok";
            IntPtr sc3 = QI(sc, IID_SwapChain3);
            if (sc3 == IntPtr.Zero) return "no IDXGISwapChain3";
            try {
                uint flags;
                hr = Method<CheckColorSpace>(sc3, SWAPCHAIN3_CHECK_COLOR_SPACE)(sc3, colorSpace, out flags);
                if (hr < 0) return "failed: " + Hr(hr);
                return (flags & 1) != 0 ? "supported" : "not supported";
            } finally { Release(sc3); }
        } finally { Release(sc); }
    }

    static OrderedDictionary Output(IntPtr op) {
        OrderedDictionary o = new OrderedDictionary();
        OutputDesc d;
        int hr = Method<GetOutputDesc>(op, OUTPUT_GET_DESC)(op, out d);
        if (hr < 0) return Error("GetDesc failed: " + Hr(hr));
        o["device"] = d.DeviceName;
        o["desktop"] = string.Format(CultureInfo.InvariantCulture, "{0}x{1} at {2},{3}", d.Right - d.Left, d.Bottom - d.Top, d.Left, d.Top);
        o["rotation"] = d.Rotation <= 1 ? "none" : ((d.Rotation - 1) * 90) + " degrees";
        DevMode dm = new DevMode(); dm.dmSize = (short)Marshal.SizeOf(typeof(DevMode));
        if (EnumDisplaySettingsW(d.DeviceName, -1, ref dm)) {
            o["mode"] = dm.dmPelsWidth + "x" + dm.dmPelsHeight;
            o["refreshHz"] = dm.dmDisplayFrequency;
            o["bitsPerPixel"] = dm.dmBitsPerPel;
            int max = 0;
            for (int m = 0; m < 4096; m++) {
                DevMode e = new DevMode(); e.dmSize = dm.dmSize;
                if (!EnumDisplaySettingsW(d.DeviceName, m, ref e)) break;
                if (e.dmPelsWidth == dm.dmPelsWidth && e.dmPelsHeight == dm.dmPelsHeight && e.dmDisplayFrequency > max) max = e.dmDisplayFrequency;
            }
            o["maxRefreshHz"] = max;
        }
        try {
            uint dx, dy;
            if (GetDpiForMonitor(d.Monitor, 0, out dx, out dy) == 0) { o["dpi"] = dx; o["scale"] = (dx * 100 / 96) + "%"; }
        } catch (Exception) { }
        IntPtr o6 = QI(op, IID_Output6);
        if (o6 != IntPtr.Zero) {
            try {
                OutputDesc1 d1;
                if (Method<GetOutputDesc1>(o6, OUTPUT6_GET_DESC1)(o6, out d1) >= 0) {
                    o["bitsPerColor"] = d1.BitsPerColor;
                    o["colorSpace"] = d1.ColorSpace == 12 ? "HDR10 (G2084 P2020)" : d1.ColorSpace == 0 ? "SDR (G22 P709)" : "DXGI color space " + d1.ColorSpace;
                    o["luminance"] = string.Format(CultureInfo.InvariantCulture, "{0:0.####} to {1:0} nits, {2:0} full frame", d1.MinLuminance, d1.MaxLuminance, d1.MaxFullFrameLuminance);
                }
                uint hc;
                if (Method<OutFlags>(o6, OUTPUT6_HW_COMPOSITION)(o6, out hc) >= 0) {
                    List<string> s = new List<string>();
                    if ((hc & 1) != 0) s.Add("fullscreen");
                    if ((hc & 2) != 0) s.Add("windowed");
                    if ((hc & 4) != 0) s.Add("cursor stretched");
                    o["hardwareComposition"] = s.Count == 0 ? "none" : string.Join(", ", s.ToArray());
                }
            } finally { Release(o6); }
        }
        IntPtr o2 = QI(op, IID_Output2);
        if (o2 != IntPtr.Zero) {
            try { o["overlays"] = Method<NoArgs>(o2, OUTPUT2_SUPPORTS_OVERLAYS)(o2) != 0; } finally { Release(o2); }
        }
        return o;
    }

    // ---- Vulkan ----
    [DllImport("vulkan-1.dll")] static extern int vkEnumerateInstanceVersion(out uint version);
    [DllImport("vulkan-1.dll")] static extern int vkEnumerateInstanceExtensionProperties(IntPtr layer, ref uint count, IntPtr props);
    [DllImport("vulkan-1.dll")] static extern int vkEnumerateInstanceLayerProperties(ref uint count, IntPtr props);
    [DllImport("vulkan-1.dll")] static extern int vkCreateInstance(ref InstanceInfo info, IntPtr alloc, out IntPtr instance);
    [DllImport("vulkan-1.dll")] static extern void vkDestroyInstance(IntPtr instance, IntPtr alloc);
    [DllImport("vulkan-1.dll")] static extern int vkEnumeratePhysicalDevices(IntPtr instance, ref uint count, IntPtr devices);
    [DllImport("vulkan-1.dll")] static extern void vkGetPhysicalDeviceProperties(IntPtr pd, IntPtr props);
    [DllImport("vulkan-1.dll")] static extern void vkGetPhysicalDeviceProperties2(IntPtr pd, IntPtr props);
    [DllImport("vulkan-1.dll")] static extern void vkGetPhysicalDeviceFeatures2(IntPtr pd, IntPtr features);
    [DllImport("vulkan-1.dll")] static extern void vkGetPhysicalDeviceMemoryProperties(IntPtr pd, IntPtr props);
    [DllImport("vulkan-1.dll")] static extern void vkGetPhysicalDeviceQueueFamilyProperties(IntPtr pd, ref uint count, IntPtr props);
    [DllImport("vulkan-1.dll")] static extern int vkEnumerateDeviceExtensionProperties(IntPtr pd, IntPtr layer, ref uint count, IntPtr props);
    [DllImport("vulkan-1.dll")] static extern int vkCreateWin32SurfaceKHR(IntPtr instance, ref SurfaceInfo info, IntPtr alloc, out ulong surface);
    [DllImport("vulkan-1.dll")] static extern void vkDestroySurfaceKHR(IntPtr instance, ulong surface, IntPtr alloc);
    [DllImport("vulkan-1.dll")] static extern int vkGetPhysicalDeviceSurfaceSupportKHR(IntPtr pd, uint family, ulong surface, out uint supported);
    [DllImport("vulkan-1.dll")] static extern int vkGetPhysicalDeviceSurfaceCapabilitiesKHR(IntPtr pd, ulong surface, IntPtr caps);
    [DllImport("vulkan-1.dll")] static extern int vkGetPhysicalDeviceSurfaceFormatsKHR(IntPtr pd, ulong surface, ref uint count, IntPtr formats);
    [DllImport("vulkan-1.dll")] static extern int vkGetPhysicalDeviceSurfacePresentModesKHR(IntPtr pd, ulong surface, ref uint count, IntPtr modes);

    [StructLayout(LayoutKind.Sequential)]
    struct AppInfo { public int sType; public IntPtr pNext, pApplicationName; public uint applicationVersion; public IntPtr pEngineName; public uint engineVersion, apiVersion; }
    [StructLayout(LayoutKind.Sequential)]
    struct InstanceInfo { public int sType; public IntPtr pNext; public uint flags; public IntPtr pApplicationInfo; public uint enabledLayerCount; public IntPtr ppEnabledLayerNames; public uint enabledExtensionCount; public IntPtr ppEnabledExtensionNames; }
    [StructLayout(LayoutKind.Sequential)]
    struct SurfaceInfo { public int sType; public IntPtr pNext; public uint flags; public IntPtr hinstance, hwnd; }

    const uint VK_1_0 = 1u << 22, VK_1_1 = VK_1_0 | (1u << 12), VK_1_2 = VK_1_0 | (2u << 12), VK_1_3 = VK_1_0 | (3u << 12);
    static readonly int H = IntPtr.Size * 2;  // sType + pNext of a chained structure

    static readonly List<IntPtr> allocations = new List<IntPtr>();
    static IntPtr Alloc(int size) {
        IntPtr p = Marshal.AllocHGlobal(size);
        allocations.Add(p);
        Marshal.Copy(new byte[size], 0, p, size);
        return p;
    }
    static void Chain(IntPtr s, int sType, IntPtr next) { Marshal.WriteInt32(s, 0, sType); Marshal.WriteIntPtr(s, IntPtr.Size, next); }
    static uint U32(IntPtr p, int offset) { return (uint)Marshal.ReadInt32(p, offset); }
    static string Text(IntPtr p, int offset) { return Marshal.PtrToStringAnsi(IntPtr.Add(p, offset)); }
    static string Ver(uint v) { return ((v >> 22) & 0x7f) + "." + ((v >> 12) & 0x3ff) + "." + (v & 0xfff); }

    static string Result(int r) {
        switch (r) {
            case -1: return "VK_ERROR_OUT_OF_HOST_MEMORY";
            case -2: return "VK_ERROR_OUT_OF_DEVICE_MEMORY";
            case -3: return "VK_ERROR_INITIALIZATION_FAILED";
            case -6: return "VK_ERROR_LAYER_NOT_PRESENT";
            case -7: return "VK_ERROR_EXTENSION_NOT_PRESENT";
            case -9: return "VK_ERROR_INCOMPATIBLE_DRIVER";
            case -1000000000: return "VK_ERROR_SURFACE_LOST_KHR";
            case -1000000001: return "VK_ERROR_NATIVE_WINDOW_IN_USE_KHR";
            default: return "VkResult " + r;
        }
    }

    // NVIDIA and Intel pack their driver versions their own way; the rest use the Vulkan encoding
    static string DriverVersion(uint vendor, uint v) {
        if (vendor == 0x10DE) return ((v >> 22) & 0x3ff) + "." + ((v >> 14) & 0xff) + "." + ((v >> 6) & 0xff) + "." + (v & 0x3f);
        if (vendor == 0x8086) return (v >> 14) + "." + (v & 0x3fff);
        return Ver(v);
    }

    static List<string> Names(int count, IntPtr props, int stride) {
        List<string> names = new List<string>();
        for (int i = 0; i < count; i++) names.Add(Text(props, i * stride));
        return names;
    }

    static List<string> InstanceExtensions() {
        uint n = 0;
        vkEnumerateInstanceExtensionProperties(IntPtr.Zero, ref n, IntPtr.Zero);
        IntPtr p = Alloc((int)Math.Max(n, 1) * 260);
        vkEnumerateInstanceExtensionProperties(IntPtr.Zero, ref n, p);
        return Names((int)n, p, 260);
    }

    static List<string> Layers() {
        uint n = 0;
        vkEnumerateInstanceLayerProperties(ref n, IntPtr.Zero);
        IntPtr p = Alloc((int)Math.Max(n, 1) * 520);
        vkEnumerateInstanceLayerProperties(ref n, p);
        return Names((int)n, p, 520);
    }

    static OrderedDictionary Vulkan(IntPtr hwnd) {
        OrderedDictionary o = new OrderedDictionary();
        uint loader = VK_1_0;
        try {
            uint v;
            if (vkEnumerateInstanceVersion(out v) == 0) loader = v;
        } catch (EntryPointNotFoundException) { }
        catch (DllNotFoundException) { return Error("the Vulkan loader (vulkan-1.dll) is not installed"); }
        o["loader"] = Ver(loader);
        List<string> available = InstanceExtensions();
        o["instanceExtensions"] = available;
        o["layers"] = Layers();
        List<string> enable = new List<string>();
        foreach (string e in new string[] { "VK_KHR_surface", "VK_KHR_win32_surface", "VK_EXT_swapchain_colorspace", "VK_KHR_get_physical_device_properties2" })
            if (available.Contains(e)) enable.Add(e);
        uint api = loader >= VK_1_1 ? VK_1_3 : VK_1_0;

        AppInfo app = new AppInfo();
        app.sType = 0; app.pApplicationName = Marshal.StringToHGlobalAnsi("diagnose"); allocations.Add(app.pApplicationName);
        app.apiVersion = api;
        IntPtr appPtr = Alloc(Marshal.SizeOf(typeof(AppInfo)));
        Marshal.StructureToPtr(app, appPtr, false);
        IntPtr names = Alloc(Math.Max(enable.Count, 1) * IntPtr.Size);
        for (int i = 0; i < enable.Count; i++) {
            IntPtr s = Marshal.StringToHGlobalAnsi(enable[i]); allocations.Add(s);
            Marshal.WriteIntPtr(names, i * IntPtr.Size, s);
        }
        InstanceInfo ii = new InstanceInfo();
        ii.sType = 1; ii.pApplicationInfo = appPtr; ii.enabledExtensionCount = (uint)enable.Count; ii.ppEnabledExtensionNames = names;
        IntPtr inst;
        int res = vkCreateInstance(ref ii, IntPtr.Zero, out inst);
        if (res != 0) { o["error"] = "vkCreateInstance failed: " + Result(res); return o; }
        o["instanceApi"] = Ver(api);
        try {
            ulong surface = 0;
            if (hwnd != IntPtr.Zero && enable.Contains("VK_KHR_win32_surface")) {
                SurfaceInfo si = new SurfaceInfo();
                si.sType = 1000009000; si.hinstance = GetModuleHandleW(null); si.hwnd = hwnd;
                res = vkCreateWin32SurfaceKHR(inst, ref si, IntPtr.Zero, out surface);
                if (res != 0) { o["surfaceError"] = Result(res); surface = 0; }
            }
            try {
                uint n = 0;
                res = vkEnumeratePhysicalDevices(inst, ref n, IntPtr.Zero);
                if (res != 0) { o["error"] = "vkEnumeratePhysicalDevices failed: " + Result(res); return o; }
                IntPtr list = Alloc((int)Math.Max(n, 1) * IntPtr.Size);
                vkEnumeratePhysicalDevices(inst, ref n, list);
                ArrayList devices = new ArrayList();
                for (int i = 0; i < n; i++) {
                    IntPtr pd = Marshal.ReadIntPtr(list, i * IntPtr.Size);
                    devices.Add(Guard(delegate { return Device(pd, api, surface); }));
                }
                o["devices"] = devices;
            } finally { if (surface != 0) vkDestroySurfaceKHR(inst, surface, IntPtr.Zero); }
        } finally { vkDestroyInstance(inst, IntPtr.Zero); }
        return o;
    }

    static readonly string[] DeviceTypes = { "other", "integrated", "discrete", "virtual", "cpu" };

    static OrderedDictionary Device(IntPtr pd, uint instanceApi, ulong surface) {
        OrderedDictionary o = new OrderedDictionary();
        IntPtr props = Alloc(2048);
        vkGetPhysicalDeviceProperties(pd, props);
        uint dapi = U32(props, 0), vendor = U32(props, 8), type = U32(props, 16);
        o["name"] = Text(props, 20);
        o["type"] = type < DeviceTypes.Length ? DeviceTypes[type] : type.ToString();
        o["api"] = Ver(dapi);
        o["vendorId"] = Hex(vendor);
        o["deviceId"] = Hex(U32(props, 12));
        o["driverVersion"] = DriverVersion(vendor, U32(props, 4));
        o["maxImageDimension2D"] = U32(props, 300);

        uint n = 0;
        vkEnumerateDeviceExtensionProperties(pd, IntPtr.Zero, ref n, IntPtr.Zero);
        IntPtr ext = Alloc((int)Math.Max(n, 1) * 260);
        vkEnumerateDeviceExtensionProperties(pd, IntPtr.Zero, ref n, ext);
        List<string> extensions = Names((int)n, ext, 260);

        if (dapi >= VK_1_1 && instanceApi >= VK_1_1) {
            bool driverProps = dapi >= VK_1_2 || extensions.Contains("VK_KHR_driver_properties");
            IntPtr p2 = Alloc(2048), drv = Alloc(1024), id = Alloc(256);
            Chain(id, 1000071004, IntPtr.Zero);                       // VkPhysicalDeviceIDProperties
            if (driverProps) Chain(drv, 1000196000, id);              // VkPhysicalDeviceDriverProperties
            Chain(p2, 1000059001, driverProps ? drv : id);           // VkPhysicalDeviceProperties2
            vkGetPhysicalDeviceProperties2(pd, p2);
            if (driverProps) {
                o["driverId"] = U32(drv, H);
                o["driverName"] = Text(drv, H + 4);
                o["driverInfo"] = Text(drv, H + 260);
            }
            if (U32(id, H + 44) != 0) o["luid"] = Luid(U32(id, H + 32), Marshal.ReadInt32(id, H + 36));
            if (dapi >= VK_1_2 || extensions.Contains("VK_KHR_timeline_semaphore")) {
                IntPtr f2 = Alloc(512), tl = Alloc(64);
                Chain(tl, 1000207000, IntPtr.Zero);                   // VkPhysicalDeviceTimelineSemaphoreFeatures
                Chain(f2, 1000059000, tl);                            // VkPhysicalDeviceFeatures2
                vkGetPhysicalDeviceFeatures2(pd, f2);
                o["timelineSemaphore"] = U32(tl, H) != 0;
            }
        }

        IntPtr mem = Alloc(1024);
        vkGetPhysicalDeviceMemoryProperties(pd, mem);
        uint heaps = Math.Min(U32(mem, 260), 16u);
        long local = 0, shared = 0;
        for (int i = 0; i < heaps; i++) {
            long size = Marshal.ReadInt64(mem, 264 + i * 16);
            if ((U32(mem, 264 + i * 16 + 8) & 1) != 0) local += size; else shared += size;
        }
        o["deviceLocalMb"] = local / 1048576;
        o["hostVisibleHeapMb"] = shared / 1048576;

        uint qn = 0;
        vkGetPhysicalDeviceQueueFamilyProperties(pd, ref qn, IntPtr.Zero);
        IntPtr qp = Alloc((int)Math.Max(qn, 1) * 24);
        vkGetPhysicalDeviceQueueFamilyProperties(pd, ref qn, qp);
        ArrayList queues = new ArrayList();
        int presentFamily = -1;
        for (int i = 0; i < qn; i++) {
            uint flags = U32(qp, i * 24);
            List<string> caps = new List<string>();
            if ((flags & 1) != 0) caps.Add("graphics");
            if ((flags & 2) != 0) caps.Add("compute");
            if ((flags & 4) != 0) caps.Add("transfer");
            if ((flags & 8) != 0) caps.Add("sparse");
            if ((flags & 0x10) != 0) caps.Add("protected");
            if ((flags & 0x20) != 0) caps.Add("video decode");
            if ((flags & 0x40) != 0) caps.Add("video encode");
            if ((flags & 0x100) != 0) caps.Add("optical flow");
            if (surface != 0) {
                uint ok;
                if (vkGetPhysicalDeviceSurfaceSupportKHR(pd, (uint)i, surface, out ok) == 0 && ok != 0) {
                    caps.Add("present");
                    if (presentFamily < 0) presentFamily = i;
                }
            }
            queues.Add(U32(qp, i * 24 + 4) + "x " + string.Join("+", caps.ToArray()));
        }
        o["queueFamilies"] = queues;
        if (surface != 0) o["surface"] = presentFamily < 0 ? (object)Error("no queue family can present to a window") : Surface(pd, surface);
        o["extensions"] = extensions;
        return o;
    }

    static string PresentMode(int m) {
        switch (m) {
            case 0: return "IMMEDIATE"; case 1: return "MAILBOX"; case 2: return "FIFO"; case 3: return "FIFO_RELAXED";
            case 1000111000: return "SHARED_DEMAND_REFRESH"; case 1000111001: return "SHARED_CONTINUOUS_REFRESH";
            case 1000361000: return "FIFO_LATEST_READY";
            default: return "mode " + m;
        }
    }
    static string Format(int f) {
        switch (f) {
            case 37: return "R8G8B8A8_UNORM"; case 43: return "R8G8B8A8_SRGB"; case 44: return "B8G8R8A8_UNORM"; case 50: return "B8G8R8A8_SRGB";
            case 58: return "A2R10G10B10_UNORM"; case 64: return "A2B10G10R10_UNORM"; case 97: return "R16G16B16A16_SFLOAT";
            default: return "format " + f;
        }
    }
    static string ColorSpace(int c) {
        switch (c) {
            case 0: return "SRGB_NONLINEAR"; case 1000104002: return "EXTENDED_SRGB_LINEAR"; case 1000104008: return "HDR10_ST2084";
            default: return "colorspace " + c;
        }
    }

    static OrderedDictionary Surface(IntPtr pd, ulong surface) {
        OrderedDictionary o = new OrderedDictionary();
        IntPtr caps = Alloc(64);
        if (vkGetPhysicalDeviceSurfaceCapabilitiesKHR(pd, surface, caps) == 0) {
            uint max = U32(caps, 4);
            o["images"] = U32(caps, 0) + " to " + (max == 0 ? "unlimited" : max.ToString());
        }
        uint n = 0;
        vkGetPhysicalDeviceSurfacePresentModesKHR(pd, surface, ref n, IntPtr.Zero);
        IntPtr modes = Alloc((int)Math.Max(n, 1) * 4);
        vkGetPhysicalDeviceSurfacePresentModesKHR(pd, surface, ref n, modes);
        List<string> pm = new List<string>();
        for (int i = 0; i < n; i++) pm.Add(PresentMode(Marshal.ReadInt32(modes, i * 4)));
        o["presentModes"] = pm;
        n = 0;
        vkGetPhysicalDeviceSurfaceFormatsKHR(pd, surface, ref n, IntPtr.Zero);
        IntPtr fmts = Alloc((int)Math.Max(n, 1) * 8);
        vkGetPhysicalDeviceSurfaceFormatsKHR(pd, surface, ref n, fmts);
        List<string> fs = new List<string>();
        for (int i = 0; i < n; i++) fs.Add(Format(Marshal.ReadInt32(fmts, i * 8)) + "/" + ColorSpace(Marshal.ReadInt32(fmts, i * 8 + 4)));
        o["formats"] = fs;
        return o;
    }
}
}
'@

# 64-bit Windows PowerShell even from a 32-bit or PowerShell 7 host: the probe must see what the application sees
function VdProbeHost {
    $root = $env:SystemRoot
    if ([Environment]::Is64BitOperatingSystem -and -not [Environment]::Is64BitProcess) {
        $p = "$root\Sysnative\WindowsPowerShell\v1.0\powershell.exe"
        if (Test-Path -LiteralPath $p) { return $p }
    }
    "$root\System32\WindowsPowerShell\v1.0\powershell.exe"
}

function VdProbe {
    # a suite installs several applications in one go; they share one probe
    $c = $global:VdProbeCache
    if ($c -and ((Get-Date) - $c.At).TotalMinutes -lt 10) { return $c.Data }
    $tmp = Join-Path ([IO.Path]::GetTempPath()) ("vi-diag-" + [guid]::NewGuid().ToString('N').Substring(0, 8))
    New-Item -ItemType Directory -Force -Path $tmp | Out-Null
    try {
        $cs = Join-Path $tmp 'probe.cs'
        $out = Join-Path $tmp 'probe.json'
        [IO.File]::WriteAllText($cs, $VdProbeSource)
        $q = { param($s) "'" + $s.Replace("'", "''") + "'" }
        $cmd = "`$ErrorActionPreference = 'Stop'; try { Add-Type -Path $(& $q $cs); `$r = [ViDiag.Probe]::Run() } " +
               "catch { `$r = @{ error = `$_.Exception.Message } }; " +
               "[IO.File]::WriteAllText($(& $q $out), (`$r | ConvertTo-Json -Depth 12))"
        $psi = New-Object Diagnostics.ProcessStartInfo
        $psi.FileName = VdProbeHost
        $psi.Arguments = '-NoProfile -NonInteractive -ExecutionPolicy Bypass -EncodedCommand ' +
                         [Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($cmd))
        $psi.UseShellExecute = $false
        $psi.CreateNoWindow = $true
        $p = [Diagnostics.Process]::Start($psi)
        if (-not $p.WaitForExit(60000)) {
            try { $p.Kill() } catch { }
            $data = [pscustomobject]@{ error = 'the GPU probe did not finish within 60 seconds (a graphics driver may be hanging)' }
        } elseif (Test-Path -LiteralPath $out) {
            $data = Get-Content -Raw -LiteralPath $out | ConvertFrom-Json
        } else {
            $data = [pscustomobject]@{ error = ('the GPU probe ended without a result (exit code 0x{0:X8}); a graphics driver may have crashed it' -f $p.ExitCode) }
        }
    } finally {
        Remove-Item -Recurse -Force -LiteralPath $tmp -ErrorAction SilentlyContinue
    }
    $global:VdProbeCache = @{ At = Get-Date; Data = $data }
    $data
}

# ---- everything else, from the registry and WMI --------------------------------------------

function VdReadRecord([string]$id) {
    $p = Join-Path (VdRegistryDir) "$id.json"
    if (Test-Path -LiteralPath $p) { try { return (Get-Content -Raw -LiteralPath $p | ConvertFrom-Json) } catch { } }
    $null
}

function VdOs {
    $cv = Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion'
    $os = Get-CimInstance Win32_OperatingSystem
    $ver = if ($null -ne $cv.CurrentMajorVersionNumber) { "$($cv.CurrentMajorVersionNumber).$($cv.CurrentMinorVersionNumber).$($cv.CurrentBuildNumber)" } else { $os.Version }
    $net = Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\NET Framework Setup\NDP\v4\Full' -ErrorAction SilentlyContinue
    $o = [ordered]@{
        name         = $os.Caption
        release      = $(if ($cv.DisplayVersion) { $cv.DisplayVersion } else { $cv.ReleaseId })
        version      = $ver
        build        = "$ver.$($cv.UBR)"
        architecture = $os.OSArchitecture
        locale       = (Get-Culture).Name
        uiLanguage   = (Get-UICulture).Name
        powershell   = "$($PSVersionTable.PSVersion) ($($PSVersionTable.PSEdition))"
        dotnet       = $(if ($net) { "4.x release $($net.Release)" } else { $null })
        uptimeHours  = [int]((Get-Date) - $os.LastBootUpTime).TotalHours
    }
    $gd = Get-ItemProperty -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers' -ErrorAction SilentlyContinue
    $o.gpuScheduling = switch ($gd.HwSchMode) { 2 { 'hardware-accelerated' } 1 { 'off' } default { 'default' } }
    try {
        $plan = (& powercfg.exe /getactivescheme) -join ' '
        if ($plan -match '\((.+)\)') { $o.powerPlan = $Matches[1] }
    } catch { }
    $bat = @(Get-CimInstance Win32_Battery -ErrorAction SilentlyContinue)
    if ($bat.Count -gt 0) {
        $o.power = if (@($bat | Where-Object { $_.BatteryStatus -eq 1 }).Count -gt 0) { "on battery ($($bat[0].EstimatedChargeRemaining)%)" } else { "plugged in ($($bat[0].EstimatedChargeRemaining)%)" }
    }
    $o
}

function VdHardware([string]$dir) {
    $cpu = @(Get-CimInstance Win32_Processor)
    $cs = Get-CimInstance Win32_ComputerSystem
    $os = Get-CimInstance Win32_OperatingSystem
    $o = [ordered]@{
        cpu         = ($cpu | Select-Object -First 1).Name.Trim()
        cores       = ($cpu | Measure-Object -Property NumberOfCores -Sum).Sum
        threads     = ($cpu | Measure-Object -Property NumberOfLogicalProcessors -Sum).Sum
        cpuMhz      = ($cpu | Select-Object -First 1).MaxClockSpeed
        memoryMb    = VdMb $cs.TotalPhysicalMemory
        freeMemoryMb = [long]($os.FreePhysicalMemory / 1KB)
        model       = (@($cs.Manufacturer, $cs.Model) | Where-Object { $_ }) -join ' '
    }
    $root = [IO.Path]::GetPathRoot($dir)
    if ($root) {
        $d = New-Object IO.DriveInfo $root
        if ($d.IsReady) {
            $o.disk = $root
            $o.diskFreeMb = VdMb $d.AvailableFreeSpace
            $o.diskSizeMb = VdMb $d.TotalSize
            $o.diskFormat = $d.DriveFormat
        }
    }
    $o
}

function VdVideoControllers {
    @(Get-CimInstance Win32_VideoController | ForEach-Object {
        [ordered]@{
            name          = $_.Name
            driverVersion = $_.DriverVersion
            driverDate    = $(if ($_.DriverDate) { $_.DriverDate.ToString('yyyy-MM-dd') } else { $null })
            status        = $_.Status
        }
    })
}

# Implicit layers load into every Vulkan application (overlays, recorders, tuning tools) and are a common
# cause of crashes at start-up, so the report lists every one the loader would find in the registry.
function VdImplicitLayers {
    $out = @()
    foreach ($root in 'HKLM:\SOFTWARE\Khronos\Vulkan\ImplicitLayers', 'HKCU:\SOFTWARE\Khronos\Vulkan\ImplicitLayers') {
        $k = Get-Item -LiteralPath $root -ErrorAction SilentlyContinue
        if (-not $k) { continue }
        foreach ($n in $k.GetValueNames()) {
            $name = $null
            try {
                $j = Get-Content -Raw -LiteralPath $n | ConvertFrom-Json
                $name = if ($j.layer) { $j.layer.name } else { (@($j.layers) | ForEach-Object { $_.name }) -join ', ' }
            } catch { $name = '(manifest not readable)' }
            $out += [ordered]@{ name = $name; enabled = ([int]$k.GetValue($n) -eq 0); manifest = $n }
        }
    }
    $out
}

function VdEnvironment {
    $o = [ordered]@{}
    foreach ($n in 'VK_ICD_FILENAMES', 'VK_DRIVER_FILES', 'VK_ADD_DRIVER_FILES', 'VK_INSTANCE_LAYERS', 'VK_LAYER_PATH',
                   'VK_ADD_LAYER_PATH', 'VK_LOADER_LAYERS_ENABLE', 'VK_LOADER_LAYERS_DISABLE', 'VK_LOADER_DRIVERS_SELECT',
                   'VK_LOADER_DRIVERS_DISABLE', 'VK_LOADER_DEBUG', 'DISABLE_LAYER_NV_OPTIMUS_1', 'JAVA_HOME', 'JAVA_TOOL_OPTIONS',
                   '_JAVA_OPTIONS', 'INSTALL_REGISTRY_DIR') {
        $v = [Environment]::GetEnvironmentVariable($n)
        if ($v) { $o[$n] = $v }
    }
    $o
}

function VdInstalls {
    $dir = VdRegistryDir
    if (-not (Test-Path -LiteralPath $dir)) { return @() }
    $prefs = Get-Item -LiteralPath 'HKCU:\Software\Microsoft\DirectX\UserGpuPreferences' -ErrorAction SilentlyContinue
    @(Get-ChildItem -LiteralPath $dir -Filter *.json | ForEach-Object {
        try { $r = Get-Content -Raw -LiteralPath $_.FullName | ConvertFrom-Json } catch { return }
        $o = [ordered]@{ id = $r.id; version = $r.version; installDir = $r.installDir; updatedAt = $r.updatedAt }
        # Settings > System > Display > Graphics: a per-program GPU choice overrides the one the program makes
        if ($prefs -and $r.installDir) {
            $mine = @($prefs.GetValueNames() | Where-Object { $_.StartsWith($r.installDir, [StringComparison]::OrdinalIgnoreCase) })
            if ($mine.Count -gt 0) { $o.gpuPreference = @($mine | ForEach-Object { "$(Split-Path $_ -Leaf): $($prefs.GetValue($_))" }) }
        }
        $o
    })
}

# ---- requirements ---------------------------------------------------------------------------

function VdCheck([string]$what, [string]$status, [string]$found) { [ordered]@{ check = $what; status = $status; found = $found } }

function VdGpuCheck($req, $probe) {
    $exts = @($req.vulkanExtensions | Where-Object { $_ })
    $parts = @()
    if ($req.vulkan) { $parts += "Vulkan $($req.vulkan)" }
    if ($exts.Count -gt 0) { $parts += "$(if ($req.vulkan) { 'with' } else { 'Vulkan with' }) $($exts -join ', ')" }
    if ($req.d3d12) { $parts += "$(if ($parts.Count -gt 0) { 'and ' })Direct3D 12 feature level $($req.d3d12)" }
    $what = "A GPU with " + ($parts -join ' ')
    if (-not $probe -or $probe.error) { return VdCheck $what 'unknown' "the GPU probe failed: $($probe.error)" }

    $adapters = @($probe.dxgi.adapters | Where-Object { $_ -and -not $_.error })
    if (-not $req.vulkan -and $exts.Count -eq 0) {
        $ok = @($adapters | Where-Object { -not $_.software -and (VdLevel $_.d3d12) -ge (VdLevel $req.d3d12) }) | Select-Object -First 1
        if ($ok) { return VdCheck $what 'ok' "$($ok.name) (feature level $($ok.d3d12))" }
        $found = (@($adapters | ForEach-Object { "$($_.name): $(if ($_.d3d12) { "feature level $($_.d3d12)" } else { 'no Direct3D 12' })" }) -join '; ')
        return VdCheck $what 'fail' $(if ($found) { $found } else { "no Direct3D 12 adapter ($($probe.dxgi.error))" })
    }
    if ($probe.vulkan.error) { return VdCheck $what 'fail' $probe.vulkan.error }
    # the GPU named is the one the application would most likely pick
    $rank = @{ discrete = 0; integrated = 1; virtual = 2; other = 3; cpu = 4 }
    $devices = @($probe.vulkan.devices | Where-Object { $_ -and -not $_.error } | Sort-Object { $rank[[string]$_.type] })
    if ($devices.Count -eq 0) { return VdCheck $what 'fail' 'Vulkan finds no GPU (no Vulkan driver is installed for it)' }
    $why = @()
    foreach ($d in $devices) {
        $miss = @()
        if ($req.vulkan -and (VdVer $d.api) -lt (VdVer $req.vulkan)) { $miss += "Vulkan $($d.api)" }
        $lacks = @($exts | Where-Object { @($d.extensions) -notcontains $_ })
        if ($lacks.Count -gt 0) { $miss += "lacks $($lacks -join ', ')" }
        if ($req.d3d12) {
            $a = $adapters | Where-Object { $d.luid -and $_.luid -eq $d.luid } | Select-Object -First 1
            if (-not $a) { $miss += 'no DXGI adapter with the same LUID' }
            elseif ((VdLevel $a.d3d12) -lt (VdLevel $req.d3d12)) { $miss += "Direct3D 12 $(if ($a.d3d12) { "feature level $($a.d3d12)" } else { 'not available' })" }
        }
        if ($miss.Count -eq 0) { return VdCheck $what 'ok' "$($d.name) (Vulkan $($d.api), $($d.type))" }
        $why += "$($d.name): $($miss -join ', ')"
    }
    VdCheck $what 'fail' ($why -join '; ')
}

function VdEvaluate($req, $data) {
    $checks = @()
    if (-not $req) { return $checks }
    if ($req.windows) {
        $have = if ($data.os.version) { $data.os.version } else { [Environment]::OSVersion.Version.ToString() }
        $checks += VdCheck "Windows $($req.windows) or newer" $(if ((VdVer $have) -ge (VdVer $req.windows)) { 'ok' } else { 'fail' }) $have
    }
    if ($req.memoryMb) {
        $m = $data.hardware.memoryMb
        $checks += VdCheck "$($req.memoryMb) MB of memory" $(if (-not $m) { 'unknown' } elseif ($m -ge $req.memoryMb) { 'ok' } else { 'fail' }) $(if ($m) { "$m MB" } else { $data.hardware.error })
    }
    if ($req.diskMb) {
        $f = $data.hardware.diskFreeMb
        $checks += VdCheck "$($req.diskMb) MB free on the install drive" $(if ($null -eq $f) { 'unknown' } elseif ($f -ge $req.diskMb) { 'ok' } else { 'fail' }) $(if ($null -ne $f) { "$f MB free on $($data.hardware.disk)" } else { 'not known' })
    }
    if ($req.vulkan -or @($req.vulkanExtensions | Where-Object { $_ }).Count -gt 0 -or $req.d3d12) {
        $checks += VdGpuCheck $req $data.gpu
    }
    $checks
}

# ---- the report -----------------------------------------------------------------------------

function VdRender($data) {
    $L = New-Object 'System.Collections.Generic.List[string]'
    function kv([string]$k, $v, [int]$indent = 2) {
        if ($null -eq $v -or "$v" -eq '') { return }
        if ($v -is [array]) { $v = $v -join ', ' }
        $L.Add((' ' * $indent) + ($k + ' ').PadRight(24 - $indent, ' ') + $v)
    }
    function head([string]$t) { $L.Add(''); $L.Add("== $t") }
    function err($o, [int]$indent = 2) { if ($o.error) { kv 'error' $o.error $indent } }

    $L.Add("$($data.app.name) - diagnostic report")
    kv 'Created' $data.createdAt 0
    kv 'Application' "$($data.app.id) $(if ($data.app.installed) { "$($data.app.installed) installed" } else { 'not installed' })$(if ($data.app.installing) { ", installing $($data.app.installing)" })" 0
    kv 'Report a problem' $data.app.issuesUrl 0
    if ($data.installError) { head 'Install error'; $L.Add("  $($data.installError)") }

    if (@($data.requirements).Count -gt 0) {
        head 'Requirements'
        $labels = @{ ok = 'ok  '; fail = 'FAIL'; unknown = '??  ' }
        foreach ($c in $data.requirements) { $L.Add(("  [{0}] {1}" -f $labels[$c.status], $c.check)); kv 'found' $c.found 9 }
    }

    head 'Windows'
    err $data.os
    kv 'Edition' $data.os.name; kv 'Release' $data.os.release; kv 'Build' $data.os.build; kv 'Architecture' $data.os.architecture
    kv 'Locale' "$($data.os.locale) (display language $($data.os.uiLanguage))"; kv 'PowerShell' $data.os.powershell; kv '.NET Framework' $data.os.dotnet
    kv 'GPU scheduling' $data.os.gpuScheduling; kv 'Power plan' $data.os.powerPlan; kv 'Power' $data.os.power; kv 'Up for' "$($data.os.uptimeHours) h"

    head 'Hardware'
    err $data.hardware
    kv 'Computer' $data.hardware.model
    kv 'Processor' "$($data.hardware.cpu), $($data.hardware.cores) cores / $($data.hardware.threads) threads, $($data.hardware.cpuMhz) MHz"
    kv 'Memory' "$($data.hardware.memoryMb) MB ($($data.hardware.freeMemoryMb) MB free)"
    if ($data.hardware.disk) { kv 'Install drive' "$($data.hardware.disk) $($data.hardware.diskFreeMb) MB free of $($data.hardware.diskSizeMb) MB ($($data.hardware.diskFormat))" }
    foreach ($v in @($data.videoControllers)) { kv 'Display adapter' "$($v.name), driver $($v.driverVersion) ($($v.driverDate))$(if ($v.status -and $v.status -ne 'OK') { ", status $($v.status)" })" }

    $g = $data.gpu
    if ($g) {
        head 'DXGI / Direct3D 12'
        err $g
        err $g.dxgi
        kv 'Tearing (VRR)' $(if ($null -ne $g.dxgi.tearing) { if ($g.dxgi.tearing) { 'supported' } else { 'not supported' } })
        kv 'High performance' $g.dxgi.highPerformance; kv 'Minimum power' $g.dxgi.minimumPower
        foreach ($a in @($g.dxgi.adapters)) {
            $L.Add('')
            if ($a.error) { kv 'adapter' $a.error; continue }
            $L.Add("  $($a.name)$(if ($a.software) { ' (software)' })")
            kv 'ids' "vendor $($a.vendorId) device $($a.deviceId) subsys $($a.subsystemId) rev $($a.revision)" 4
            kv 'LUID' $a.luid 4
            kv 'memory' "$($a.dedicatedVideoMb) MB dedicated, $($a.sharedSystemMb) MB shared" 4
            kv 'D3D12' $(if ($a.d3d12) { "feature level $($a.d3d12)" } else { "not available ($($a.d3d12Error))" }) 4
            if ($a.swapchain) {
                if ($a.swapchain.error) { kv 'swapchain' $a.swapchain.error 4 }
                else { kv 'swapchain' "flip-discard BGRA8: $($a.swapchain.flipDiscard); 10-bit HDR10: $($a.swapchain.hdr10)" 4 }
            }
            foreach ($op in @($a.outputs)) {
                if ($op.error) { kv 'output' $op.error 4; continue }
                kv "output $($op.device -replace '^\\\\\.\\', '')" "$($op.mode) @ $($op.refreshHz) Hz (up to $($op.maxRefreshHz) Hz), $($op.bitsPerPixel) bpp, scale $($op.scale)" 4
                kv '' "desktop $($op.desktop), rotation $($op.rotation)" 6
                if ($op.colorSpace) { kv '' "$($op.colorSpace), $($op.bitsPerColor) bits per colour, $($op.luminance)" 6 }
                if ($null -ne $op.overlays -or $op.hardwareComposition) { kv '' "overlays $(if ($op.overlays) { 'yes' } else { 'no' }), hardware composition $($op.hardwareComposition)" 6 }
            }
        }

        head 'Vulkan'
        $vk = $g.vulkan
        err $vk
        kv 'Loader' $vk.loader; kv 'Instance' $vk.instanceApi; kv 'Surface' $vk.surfaceError
        foreach ($d in @($vk.devices)) {
            $L.Add('')
            if ($d.error) { kv 'device' $d.error; continue }
            $L.Add("  $($d.name) ($($d.type))")
            kv 'API' $d.api 4
            kv 'driver' "$(if ($d.driverName) { "$($d.driverName) $($d.driverInfo)" } else { $d.driverVersion }) (version $($d.driverVersion)$(if ($null -ne $d.driverId) { ", id $($d.driverId)" }))" 4
            kv 'ids' "vendor $($d.vendorId) device $($d.deviceId)" 4
            kv 'LUID' $d.luid 4
            kv 'memory' "$($d.deviceLocalMb) MB device-local, $($d.hostVisibleHeapMb) MB other heaps" 4
            kv 'timeline semaphore' $(if ($null -ne $d.timelineSemaphore) { if ($d.timelineSemaphore) { 'yes' } else { 'no' } }) 4
            kv 'max image 2D' $d.maxImageDimension2D 4
            kv 'queues' $d.queueFamilies 4
            if ($d.surface) {
                if ($d.surface.error) { kv 'present' $d.surface.error 4 }
                else { kv 'present modes' $d.surface.presentModes 4; kv 'images' $d.surface.images 4; kv 'formats' $d.surface.formats 4 }
            }
            kv 'extensions' "$(@($d.extensions).Count) (listed at the end)" 4
        }
        $layers = @($data.implicitLayers)
        if ($layers.Count -gt 0) {
            $L.Add('')
            $L.Add('  Implicit layers (loaded into every Vulkan program):')
            foreach ($l in $layers) { kv "$(if ($l.enabled) { 'on ' } else { 'off' })" "$($l.name)  $($l.manifest)" 4 }
        }
        if (@($vk.layers).Count -gt 0) { kv 'Available layers' $vk.layers }
    }

    head 'Environment'
    if (@($data.environment.Keys).Count -eq 0) { $L.Add('  (no variables that affect Vulkan or Java are set)') }
    foreach ($k in $data.environment.Keys) { kv $k $data.environment[$k] }

    head 'Installed applications'
    if (@($data.installs).Count -eq 0) { $L.Add('  (none)') }
    foreach ($i in @($data.installs)) {
        kv $i.id "$($i.version) in $($i.installDir) (updated $($i.updatedAt))"
        foreach ($p in @($i.gpuPreference)) { if ($p) { kv '' "GPU preference: $p" 4 } }
    }

    if ($g -and $g.vulkan.devices) {
        foreach ($d in @($g.vulkan.devices | Where-Object { $_.extensions })) {
            head "Vulkan device extensions: $($d.name)"
            $line = ' '
            foreach ($e in @($d.extensions)) {
                if ($line.Length + $e.Length -gt 110) { $L.Add($line); $line = ' ' }
                $line += " $e"
            }
            if ($line.Trim()) { $L.Add($line) }
        }
        if (@($g.vulkan.instanceExtensions).Count -gt 0) { head 'Vulkan instance extensions'; $L.Add('  ' + (@($g.vulkan.instanceExtensions) -join ' ')) }
    }
    ($L -join "`r`n") + "`r`n"
}

# The user's own name stays out of a report that may be posted publicly.
function VdRedact([string]$text) {
    if ($env:USERPROFILE) { $text = [regex]::Replace($text, [regex]::Escape($env:USERPROFILE), '%USERPROFILE%', 'IgnoreCase') }
    if ($env:USERPROFILE) { $text = [regex]::Replace($text, [regex]::Escape($env:USERPROFILE.Replace('\', '\\')), '%USERPROFILE%', 'IgnoreCase') }
    if ($env:USERNAME) { $text = [regex]::Replace($text, '(?<=\\)' + [regex]::Escape($env:USERNAME) + '(?=\\)', '<user>', 'IgnoreCase') }
    $text
}

function VdRun {
    param([string]$Out, [switch]$Copy, [switch]$Json, [switch]$Check, [string]$Requires, [string]$InstallDir, [string]$Installing, [string]$InstallError)
    $ProgressPreference = 'SilentlyContinue'
    $id = $DiagCfg.id
    $req = if ($Requires) { $Requires | ConvertFrom-Json } else { $DiagCfg.system }
    $rec = VdReadRecord $id
    $dir = if ($InstallDir) { $InstallDir } elseif ($rec) { $rec.installDir } else { $env:LOCALAPPDATA }
    $needGpu = -not $Check -or $InstallError -or $req.vulkan -or @($req.vulkanExtensions | Where-Object { $_ }).Count -gt 0 -or $req.d3d12

    if (-not $Check) { Write-Host "Collecting diagnostics for $($DiagCfg.name)$(if ($needGpu) { ' (the GPU probe takes a few seconds)' })..." }
    $data = [ordered]@{
        createdAt        = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ')
        app              = [ordered]@{ id = $id; name = $DiagCfg.name; installed = $rec.version; installing = $Installing; issuesUrl = $DiagCfg.issuesUrl }
        installError     = $InstallError
        requirements     = @()
        os               = VdTry { VdOs }
        hardware         = VdTry { VdHardware $dir }
        videoControllers = VdTry { VdVideoControllers }
        gpu              = $(if ($needGpu) { VdTry { VdProbe } } else { $null })
        implicitLayers   = VdTry { VdImplicitLayers }
        environment      = VdTry { VdEnvironment }
        installs         = VdTry { VdInstalls }
    }
    $data.requirements = @(VdEvaluate $req $data)

    $reportDir = Join-Path (Split-Path (VdRegistryDir) -Parent) 'diagnostics'
    if (-not $Out) {
        New-Item -ItemType Directory -Force -Path $reportDir | Out-Null
        $Out = Join-Path $reportDir ("$id-" + (Get-Date).ToString('yyyyMMdd-HHmmss') + $(if ($Json) { '.json' } else { '.txt' }))
        # keep the last ten
        Get-ChildItem -LiteralPath $reportDir -Filter "$id-*" | Sort-Object LastWriteTime -Descending | Select-Object -Skip 10 |
            Remove-Item -Force -ErrorAction SilentlyContinue
    }
    $text = if ($Json) { $data | ConvertTo-Json -Depth 12 } else { VdRender $data }
    $text = VdRedact $text
    [IO.File]::WriteAllText($Out, $text, (New-Object Text.UTF8Encoding $false))

    $failed = @($data.requirements | Where-Object { $_.status -eq 'fail' })
    $unknown = @($data.requirements | Where-Object { $_.status -eq 'unknown' })
    $result = [pscustomobject]@{ ok = $failed.Count -eq 0; failed = $failed; unknown = $unknown; report = $Out; issuesUrl = $DiagCfg.issuesUrl }
    if ($Check) { return $result }

    Write-Host ""
    foreach ($c in $data.requirements) {
        $color = switch ($c.status) { 'ok' { 'Green' } 'fail' { 'Red' } default { 'Yellow' } }
        Write-Host ("  [{0}] {1}: {2}" -f $c.status, $c.check, $c.found) -ForegroundColor $color
    }
    if ($Copy) { try { Set-Clipboard -Value $text; Write-Host "The report is on the clipboard." } catch { Write-Warning "Could not copy the report: $($_.Exception.Message)" } }
    Write-Host "Report: $Out" -ForegroundColor Cyan
    if ($DiagCfg.issuesUrl) { Write-Host "To report a problem, attach it at $($DiagCfg.issuesUrl)" }
}

$VdArgs = @{}
for ($VdI = 0; $VdI -lt $args.Count; $VdI++) {
    switch -Regex ([string]$args[$VdI]) {
        '^-Out$' { $VdI++; $VdArgs.Out = $args[$VdI] }
        '^-Copy$' { $VdArgs.Copy = $true }
        '^-Json$' { $VdArgs.Json = $true }
        '^-Check$' { $VdArgs.Check = $true }
        '^-Requires$' { $VdI++; $VdArgs.Requires = $args[$VdI] }
        '^-InstallDir$' { $VdI++; $VdArgs.InstallDir = $args[$VdI] }
        '^-Installing$' { $VdI++; $VdArgs.Installing = $args[$VdI] }
        '^-InstallError$' { $VdI++; $VdArgs.InstallError = $args[$VdI] }
        default { Write-Warning "Ignoring unknown argument: $($args[$VdI])" }
    }
}
if ($VdArgs.Check) {
    VdRun @VdArgs
} else {
    try { VdRun @VdArgs } catch { Write-Host "ERROR: $($_.Exception.Message)" -ForegroundColor Red }
}
